const v = $json.from_type === 'phone'
  ? '+234' + $json.from_value.replace(/\D/g,'').replace(/^(234|0)/,'')
  : $json.from_value.trim().toLowerCase();
return { ...$json, from_value: v };

const m = $('Normalise').item.json;
const phone = (m.text.match(/(\+?234|\b0)[789][01]\d[\s-]?\d{3}[\s-]?\d{4}/) || [])[0];
const email = (m.text.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [])[0];
const typed = phone ? '+234' + phone.replace(/\D/g, '').replace(/^(234|0)/, '') : email ? email.toLowerCase() : '';
return { customer_id: $json.customer_id, typed_value: typed };

