const m = $('Normalise').item.json;
const c = $('Customer').item.json;
const order = (m.text.match(/\bHL-\d+\b/i) || [''])[0].toUpperCase();
return { ...m, customer_id: c.customer_id, identity_verified: c.identity_verified === true,
  needs_verification: !!$json.suggested_customer_id || c.identity_verified !== true, order_ref: order };

// Priority: safety or legal -> complaint or refund -> order problem -> buying question -> general question -> praise.
const m = $('Message context').item.json;
const conv = $('Upsert conversation').item.json;
const l = $json.output;
const legal = /lawyer|police|court|sue/i.test(m.text);
let priority, assigned_to, minutes;
if (l.topic === 'food safety' || legal) { priority = 1; assigned_to = 'Tolu'; minutes = 60; }
else if (l.intent === 'complaint' || l.topic === 'refund') { priority = 2; assigned_to = 'Tolu'; minutes = 60; }
else if (m.order_ref || l.topic === 'late delivery') { priority = 3; assigned_to = 'Bisi'; minutes = 15; }
else if (l.intent === 'lead') { priority = 4; assigned_to = 'Tolu'; minutes = 60; }
else if (l.intent === 'question') { priority = 5; assigned_to = 'agent'; minutes = 5; }
else { priority = 6; assigned_to = 'agent'; minutes = 5; }
// Allowed reply on the channel (5.1 and 5.5 rules). The customer just wrote, so the window is open now.
const sinceCustomer = (Date.now() - new Date(m.received_at)) / 36e5;
const allowed_reply = m.channel === 'email' ? true : sinceCustomer <= 24;
return { ...m, conversation_id: conv.conversation_id, needs_verification: conv.needs_verification === true || m.needs_verification,
  intent: l.intent, topic: l.topic, urgent: l.urgent, priority, assigned_to,
  sla_due_at: new Date(new Date(m.received_at).getTime() + minutes * 6e4).toISOString(), allowed_reply };

