const m = $('Priority, owner, target').item.json;
const out = $('Sage Desk agent').item.json.output;
let text = out.reply_text;
let assigned = m.assigned_to;
let decided = null;
try { decided = $('Write decision').item.json; } catch (e) { decided = null; }
if (decided && decided.type) text += `\n\nUpdate: Tolu has approved your ${decided.type} (${decided.value}).`;
else if (out.decision_request && out.decision_request.type) assigned = 'Tolu';
return { conversation_id: m.conversation_id, customer_id: m.customer_id, channel: m.channel, thread_id: m.thread_id,
  reply_to_message_id: m.raw_id, last_customer_msg_at: m.received_at, text, sent_by: 'agent', assigned_to: assigned };

const p = $('Reply plan').first().json;
const name = { whatsapp: 'WhatsApp', email: 'email', instagram: 'Instagram', facebook: 'Messenger' }[p.channel] || p.channel;
return $input.all().filter(i => i.json.channel).map(i => ({ json: { ...i.json, conversation_id: p.conversation_id,
  text: `We've replied on ${name} so everything's in one place.`, sent_by: 'agent' } }));
